#!/bin/bash
# Launch AWS Spot Instance for ML Training
# Usage: ./scripts/launch_spot_training.sh [instance-type] [key-name]

set -e

INSTANCE_TYPE="${1:-g4dn.xlarge}"  # Default: g4dn.xlarge (1x T4 GPU, 4 vCPU, 16GB RAM)
KEY_NAME="${2:-}"  # Your EC2 key pair name
REGION="${AWS_REGION:-us-east-1}"

# Spot instance configuration
MAX_PRICE="0.50"  # Maximum price per hour (adjust based on current spot prices)
INSTANCE_COUNT=1

echo "🚀 Launching AWS Spot Instance for ML Training"
echo "   Instance Type: $INSTANCE_TYPE"
echo "   Region: $REGION"
echo "   Max Price: \$$MAX_PRICE/hour"

# Check if key name is provided
if [ -z "$KEY_NAME" ]; then
    echo "⚠️  No key name provided. Listing available key pairs..."
    aws ec2 describe-key-pairs --region "$REGION" --query 'KeyPairs[*].KeyName' --output table
    echo ""
    read -p "Enter key pair name: " KEY_NAME
fi

# Get latest Deep Learning AMI (PyTorch GPU)
echo "📦 Finding latest Deep Learning AMI..."
AMI_ID=$(aws ec2 describe-images \
    --owners amazon \
    --filters \
        "Name=name,Values=Deep Learning AMI GPU PyTorch*" \
        "Name=architecture,Values=x86_64" \
        "Name=state,Values=available" \
    --query 'Images | sort_by(@, &CreationDate) | [-1].ImageId' \
    --output text \
    --region "$REGION")

if [ -z "$AMI_ID" ] || [ "$AMI_ID" == "None" ]; then
    echo "⚠️  Deep Learning AMI not found, using Ubuntu Server..."
    AMI_ID=$(aws ec2 describe-images \
        --owners 099720109477 \
        --filters "Name=name,Values=ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*" \
        --query 'Images | sort_by(@, &CreationDate) | [-1].ImageId' \
        --output text \
        --region "$REGION")
fi

echo "   Using AMI: $AMI_ID"

# Create spot instance request
echo "📝 Creating spot instance request..."

SPOT_REQUEST_ID=$(aws ec2 request-spot-instances \
    --instance-count "$INSTANCE_COUNT" \
    --launch-specification "{
        \"ImageId\": \"$AMI_ID\",
        \"InstanceType\": \"$INSTANCE_TYPE\",
        \"KeyName\": \"$KEY_NAME\",
        \"SecurityGroupIds\": [],
        \"IamInstanceProfile\": {
            \"Name\": \"\"
        },
        \"BlockDeviceMappings\": [{
            \"DeviceName\": \"/dev/sda1\",
            \"Ebs\": {
                \"VolumeSize\": 100,
                \"VolumeType\": \"gp3\",
                \"DeleteOnTermination\": true
            }
        }]
    }" \
    --spot-price "$MAX_PRICE" \
    --type "one-time" \
    --region "$REGION" \
    --query 'SpotInstanceRequests[0].SpotInstanceRequestId' \
    --output text)

if [ -z "$SPOT_REQUEST_ID" ] || [ "$SPOT_REQUEST_ID" == "None" ]; then
    echo "❌ Failed to create spot instance request"
    exit 1
fi

echo "✅ Spot request created: $SPOT_REQUEST_ID"
echo "⏳ Waiting for instance to launch..."

# Wait for instance to be fulfilled
aws ec2 wait spot-instance-request-fulfilled \
    --spot-instance-request-ids "$SPOT_REQUEST_ID" \
    --region "$REGION" 2>/dev/null || true

# Get instance ID
INSTANCE_ID=$(aws ec2 describe-spot-instance-requests \
    --spot-instance-request-ids "$SPOT_REQUEST_ID" \
    --region "$REGION" \
    --query 'SpotInstanceRequests[0].InstanceId' \
    --output text)

if [ -z "$INSTANCE_ID" ] || [ "$INSTANCE_ID" == "None" ]; then
    echo "⚠️  Instance not yet available. Check status with:"
    echo "   aws ec2 describe-spot-instance-requests --spot-instance-request-ids $SPOT_REQUEST_ID --region $REGION"
    exit 1
fi

echo "✅ Instance launched: $INSTANCE_ID"

# Wait for instance to be running
echo "⏳ Waiting for instance to be running..."
aws ec2 wait instance-running --instance-ids "$INSTANCE_ID" --region "$REGION"

# Get public IP
PUBLIC_IP=$(aws ec2 describe-instances \
    --instance-ids "$INSTANCE_ID" \
    --region "$REGION" \
    --query 'Reservations[0].Instances[0].PublicIpAddress' \
    --output text)

echo ""
